
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.794515378756557e+00, -4.700812401797886e+00, -4.569527099157343e+00, -4.387685978809778e+00, -4.139914820129809e+00, -3.810045089369858e+00, -3.384756263297156e+00, -2.859160760727093e+00, -2.240990808492716e+00, -1.559189902959049e+00, -9.528579530572395e-01, -6.656138157072222e-01, -6.192477843249536e-01, -5.260089582804681e-01, -3.696110180599960e-01, -2.119698177278818e-01, -9.500233206979894e-02, -3.154060429221706e-02, -6.767687366014690e-03, -7.611656939357381e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


